SELECT TOP (1) @ImportedSplitId = SplitId FROM dbo.WorkoutSplits
WHERE SourceUrl = N'https://www.muscleandstrength.com/workouts/muscle-and-strength-30-day-womens-workout' OR (SourceUrl IS NULL AND Name = N'Muscle & Strength''s 30 Day Workout Plan For Women');
