WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/high-protein-tuna-bake-pasta' OR (SourceUrl IS NULL AND Title=N'High Protein Tuna Bake Pasta Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'High Protein Tuna Bake Pasta Recipe', N'Lunch', N'This high protein tuna bake recipe is a delicious dish that is perfect post-workout, easy to make and only requires some simple household ingredients!', 285, 33, 18, 9, NULL, 1, 10006, N'https://www.muscleandstrength.com/recipes/high-protein-tuna-bake-pasta', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/tuna-bake-feature.jpg', N'Makes 2-3 servings.', N'Boil pasta on medium temperature for 10 mins. Season with a dash of salt if desired. Empty both cans of tuna into a large bowl. Add spinach, sweetcorn, broccoli and mushrooms. Mix well with garlic and herbs. Add drained pasta to bowl and mix again. Add contents of bowl into a level ovenproof dish. Add cheese and black pepper on top and bake for 15-20 mins in the oven on 200 degrees celcius. Remove from oven when golden color. Serve on plate and enjoy!', N'["Lunch Recipes","Dinner Recipes"]', N'{"calories_kcal":"285","protein_g":"33","carbs_g":"18","fat_g":"9"}', 164100);
END
