WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/banana-walnut-protein-bar' OR (SourceUrl IS NULL AND Title=N'Banana Walnut Protein Bars Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Banana Walnut Protein Bars Recipe', N'Snack', N'This protein bar recipe combines your favorite vanilla protein powder with bananas, oatmeal, cinnamon and walnuts to make 9 amazingly tasty bars.', 204, 16, 22, 7, NULL, 1, 10008, N'https://www.muscleandstrength.com/recipes/banana-walnut-protein-bar', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/walnut-protein-bar-450.jpg', N'Makes 9 bars.', N'In a large bowl, add all dry ingredients (oats, protein, walnuts, cinnamon) and stir. In a separate bowl, mash bananas and add egg whites and vanilla and stir. Pour wet ingredients into the bowl with the dry ingredients and combine until evenly mixed. Scoop mixture into a 9x9 Pyrex dish and bake at 350 degrees F for 15 minutes. Optional topping: prior to baking, combine a calorie free sweetener such as Stevia, Splenda, Truvia, etc. with some cinnamon. Pour the cinnamon sweetener on top of the mixture, then bake. You may also top with melted dark chocolate after cooling. Makes 9 bars.', N'["Protein Bar Recipes"]', N'{"calories_kcal":"204","protein_g":"16","carbs_g":"22","fat_g":"7"}', 119000);
END
