DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/spicy-scrambled-eggs.html' OR (SourceUrl IS NULL AND Title=N'Spicy Scrambled Eggs Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Spicy Scrambled Eggs Recipe', N'Breakfast', N'Sick of boring scrambled eggs? Eggs are a cheap source of protein, but like any food, if you eat them too often they get boring. So spice up regular scrambled eggs by using this recipe!', 507, 50, 34, 19, NULL, 1, 10020, N'https://www.muscleandstrength.com/recipes/spicy-scrambled-eggs.html', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/spicyeggs.png', N'I like to have the eggs scrambled on toast because its easy and only takes a few minutes. You could also use the mix to make an omelette. Serving on a bed of spinach leaves adds color, flavor and vitamins.', N'Grab a small non-stick frying pan and spray a small amount of olive oil cooking spray to coat the pan. In a small mixing bowl add 2 whole eggs and 4 egg whites. Whisk until the egg yolks and whites mix. Add 1/4 of onion, 1 clove of garlic and 1 whole red chilli - all finely chopped. Now add 50g of cottage cheese and a pinch of mixed herbs. Whisk this mix fully. With the frying pan at moderate heat, add the contents of the mixing bowl. Put your toast in the toaster now. Gently stir the contents to scramble the eggs. Once eggs are scrambled add them to toast on a large plate.', N'["Breakfast Recipes"]', N'{"calories_kcal":"507","protein_g":"50","carbs_g":"34","fat_g":"19"}', 93400);
END
ELSE UPDATE dbo.MealSuggestions SET
