DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/lemon-thyme-roast-chicken.html' OR (SourceUrl IS NULL AND Title=N'Lemon-Thyme Roast Chicken Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Lemon-Thyme Roast Chicken Recipe', N'Dinner', N'Who doesn''t like roast chicken? How about giving this Lemon-Thyme Roast Chicken a try.', 165, 25, 1, 6, NULL, 1, 10052, N'https://www.muscleandstrength.com/recipes/lemon-thyme-roast-chicken.html', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/lemon-thyme-450.jpg', N'Lemon-Thyme roast chicken can be served with almost anything! Brown rice and salad, garden vegetables with bolied whole potatoes, roast vegetables...use your imagination!', N'Preheat oven to 350deg F. Sprinkle chicken cavities with 1/2 teaspoon of the pepper and 1/4 teaspoon of the salt. On work surface, roll lemons, pressing down slightly with heel of your hand, (go easy since I know you weight train, press lightly) until softened. With skewer or toothpick, pierce each lemon 15 times about 1" deep. Place pierced lemons, 5 garlic cloves and thyme into large cavity of chicken; place remaining garlic clove into small cavity. Truss chicken. Sprinkle chicken evenly with remaining 1/2 teaspoon pepper and 1/4 teaspoon salt. Place chicken, breast-side up, onto rack in large roasting pan; roast 2-2 1/4 hours, until chicken is cooked through and juices run clear when pierced with fork or meat thermometer inserted into thickest portion of thigh registers 180deg F. Remove from oven; let stand 10 minutes. Remove and discard skin from chicken and lemons, garlic and thyme from cavities; carve chicken. Serve garnished with additional thyme sprigs.', N'["Low Carb Recipes","Dinner Recipes"]', N'{"calories_kcal":"165","protein_g":"25","carbs_g":"1","fat_g":"6"}', 43600);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Lemon-Thyme Roast Chicken Recipe', MealType=N'Dinner', Description=N'Who doesn''t like roast chicken? How about giving this Lemon-Thyme Roast Chicken a try.', CaloriesKcal=165, ProteinG=25, CarbsG=1, FatsG=6,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10052, SourceUrl=N'https://www.muscleandstrength.com/recipes/lemon-thyme-roast-chicken.html', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/lemon-thyme-450.jpg', ServingSuggestion=N'Lemon-Thyme roast chicken can be served with almost anything! Brown rice and salad, garden vegetables with bolied whole potatoes, roast vegetables...use your imagination!', ContentText=N'Preheat oven to 350deg F. Sprinkle chicken cavities with 1/2 teaspoon of the pepper and 1/4 teaspoon of the salt. On work surface, roll lemons, pressing down slightly with heel of your hand, (go easy since I know you weight train, press lightly) until softened. With skewer or toothpick, pierce each lemon 15 times about 1" deep. Place pierced lemons, 5 garlic cloves and thyme into large cavity of chicken; place remaining garlic clove into small cavity. Truss chicken. Sprinkle chicken evenly with remaining 1/2 teaspoon pepper and 1/4 teaspoon salt. Place chicken, breast-side up, onto rack in large roasting pan; roast 2-2 1/4 hours, until chicken is cooked through and juices run clear when pierced with fork or meat thermometer inserted into thickest portion of thigh registers 180deg F. Remove from oven; let stand 10 minutes. Remove and discard skin from chicken and lemons, garlic and thyme from cavities; carve chicken. Serve garnished with additional thyme sprigs.', CategoriesJson=N'["Low Carb Recipes","Dinner Recipes"]', SourceMacrosJson=N'{"calories_kcal":"165","protein_g":"25","carbs_g":"1","fat_g":"6"}', ReadCount=43600
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'One 4-pound 8-ounce roasting chicken');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'1 tsp freshly ground black pepper');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'1/2 teaspoon salt');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'2 large lemons');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 5, N'6 garlic cloves, peeled');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 6, N'Six 4" fresh thyme sprigs or 2 teaspoons dried thyme leaves');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 7, N'Additional fresh thyme sprigs, to garnish');
DELETE FROM dbo.MealSuggestionInstructions WHERE MealSuggestionId=@ImportedMealSuggestionId;
GO

