DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/healthy-chocolate-raspberry-dessert' OR (SourceUrl IS NULL AND Title=N'Healthy Chocolate Raspberry Dessert Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Healthy Chocolate Raspberry Dessert Recipe', N'Snack', N'An easy to make and healthy dessert that won''t derail your eating plan. This delicious recipe combines dark chocolate, yogurt and raspberries.', 159, 9, 21, 5, NULL, 1, 10057, N'https://www.muscleandstrength.com/recipes/healthy-chocolate-raspberry-dessert', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/healthy-raspberry-dessert-450.jpg', N'Makes 4 servings.', N'Have a sweet tooth and need a quick and satisfying dessert that won''t ruin your diet or eating plan? Then try this delicious and easy to make recipe. If you are using frozen raspberries, gently defrost them in a microwave until they are at approximately room temperature. Next, slowly melt the dark chocolate in the microwave, or on the stovetop using a double boiler. Combine the raspberries, yogurt and dark chocolate, and gently fold the ingredients until the chocolate and yogurt are blended. Pour into dessert bowls or cups and chill. Optional: top with fresh raspberries, blueberries and crushed almonds or pistachios. If you are bulking and looking to add a few more calories use Greek yogurt instead of plain yogurt. This will add about 60 calories per serving.', N'["Snack Recipes"]', N'{"calories_kcal":"159","protein_g":"9","carbs_g":"21","fat_g":"5"}', 41500);
END
