DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/kasein-avocado-brownies' OR (SourceUrl IS NULL AND Title=N'Double Chocolate Protein Avocado Brownies Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Double Chocolate Protein Avocado Brownies Recipe', N'Snack', N'Indulge in something sweet with these double chocolate protein avocado brownies. They''re the perfect guilt-free treat to satisfy your sweet tooth!', 174, 8, 17, 8, NULL, 1, 10075, N'https://www.muscleandstrength.com/recipes/kasein-avocado-brownies', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/brownies-feature.jpg', N'Makes 9 servings.', N'Line an 8 x 8 pan with parchment paper, spray, and preheat oven to 350F. Melt 2 oz of the dark chocolate in microwave (20 second intervals) In food processor, add the avocados, coconut sugar, instant coffee, and vanilla extract. Process until smooth and creamy Add the eggs and mix until smooth In a separate bowl, whisk together the Kasein, cocoa powder, almond meal, and salt. Then add to the food processor with the other ingredients. Mixing until combined. Remove blade and add the remaining 2oz of chocolate chips and with a rubber spatula, mix into the batter. You do not want to over mix or it could make the brownies tough. So mix until just incorporated. Pour batter into a parchment paper lined 8 x 8 size pan. Option: sprinkle top with chocolate chips. Bake at 350F for 30-35 minutes. Allow to cool and cut into 9 squares. Enjoy!!', N'["High Protein Recipes","Snack Recipes","Vegetarian Recipes"]', N'{"calories_kcal":"174","protein_g":"8","carbs_g":"17","fat_g":"8"}', 30600);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Double Chocolate Protein Avocado Brownies Recipe', MealType=N'Snack', Description=N'Indulge in something sweet with these double chocolate protein avocado brownies. They''re the perfect guilt-free treat to satisfy your sweet tooth!', CaloriesKcal=174, ProteinG=8, CarbsG=17, FatsG=8,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10075, SourceUrl=N'https://www.muscleandstrength.com/recipes/kasein-avocado-brownies', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/brownies-feature.jpg', ServingSuggestion=N'Makes 9 servings.', ContentText=N'Line an 8 x 8 pan with parchment paper, spray, and preheat oven to 350F. Melt 2 oz of the dark chocolate in microwave (20 second intervals) In food processor, add the avocados, coconut sugar, instant coffee, and vanilla extract. Process until smooth and creamy Add the eggs and mix until smooth In a separate bowl, whisk together the Kasein, cocoa powder, almond meal, and salt. Then add to the food processor with the other ingredients. Mixing until combined. Remove blade and add the remaining 2oz of chocolate chips and with a rubber spatula, mix into the batter. You do not want to over mix or it could make the brownies tough. So mix until just incorporated. Pour batter into a parchment paper lined 8 x 8 size pan. Option: sprinkle top with chocolate chips. Bake at 350F for 30-35 minutes. Allow to cool and cut into 9 squares. Enjoy!!', CategoriesJson=N'["High Protein Recipes","Snack Recipes","Vegetarian Recipes"]', SourceMacrosJson=N'{"calories_kcal":"174","protein_g":"8","carbs_g":"17","fat_g":"8"}', ReadCount=30600
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
