INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'Remove blade and add the remaining 2oz of chocolate chips and with a rubber spatula, mix into the batter. You do not want to over mix or it could make the brownies tough. So mix until just incorporated.');
