DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/protein-chili-dog' OR (SourceUrl IS NULL AND Title=N'Protein Packed Chili Dog Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Protein Packed Chili Dog Recipe', N'Lunch', N'Fire up the grill and get your appetite ready. These protein packed chili dogs are bound to satisfy your taste buds while aiding your gains outside the gym!', 531, 55, 44, 15, NULL, 1, 10080, N'https://www.muscleandstrength.com/recipes/protein-chili-dog', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/chili-dog-feature.jpg', N'Makes 3 servings. 1 serving = 2 hotdogs', N'Combine all ingredients from ground turkey breast through cinnamon in a pan over medium heat Cook for 3-4 minutes Reduce heat to medium/low and allow to simmer While chili is simmering Place hotdogs on a heat grilled and cook until desired temperature Grill rolls, if desired When hotdogs are done cooking, place into buns Evenly divide chili among 6 hotdogs Top with onion Enjoy! Notes: *Ground beef or beef hotdogs would also work well here. *Make this vegetarian/vegan friendly by using beans in place of ground turkey in the chili recipe and using your favorite tofurkey dog. *You can make this into a Chili Cheese Dog by adding reduced fat cheddar cheese! *You can make this low carb by leaving out the rolls. This will reduce your carbs by around 36g depending on brand. *THIS chili recipe would also work well with this too!', N'["High Protein Recipes","Snack Recipes","Lunch Recipes","Dinner Recipes","BBQ/Grill Recipes"]', N'{"calories_kcal":"531","protein_g":"55","carbs_g":"44","fat_g":"15"}', 29700);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Protein Packed Chili Dog Recipe', MealType=N'Lunch', Description=N'Fire up the grill and get your appetite ready. These protein packed chili dogs are bound to satisfy your taste buds while aiding your gains outside the gym!', CaloriesKcal=531, ProteinG=55, CarbsG=44, FatsG=15,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10080, SourceUrl=N'https://www.muscleandstrength.com/recipes/protein-chili-dog', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/chili-dog-feature.jpg', ServingSuggestion=N'Makes 3 servings. 1 serving = 2 hotdogs', ContentText=N'Combine all ingredients from ground turkey breast through cinnamon in a pan over medium heat Cook for 3-4 minutes Reduce heat to medium/low and allow to simmer While chili is simmering Place hotdogs on a heat grilled and cook until desired temperature Grill rolls, if desired When hotdogs are done cooking, place into buns Evenly divide chili among 6 hotdogs Top with onion Enjoy! Notes: *Ground beef or beef hotdogs would also work well here. *Make this vegetarian/vegan friendly by using beans in place of ground turkey in the chili recipe and using your favorite tofurkey dog. *You can make this into a Chili Cheese Dog by adding reduced fat cheddar cheese! *You can make this low carb by leaving out the rolls. This will reduce your carbs by around 36g depending on brand. *THIS chili recipe would also work well with this too!', CategoriesJson=N'["High Protein Recipes","Snack Recipes","Lunch Recipes","Dinner Recipes","BBQ/Grill Recipes"]', SourceMacrosJson=N'{"calories_kcal":"531","protein_g":"55","carbs_g":"44","fat_g":"15"}', ReadCount=29700
