DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/low-carb-chicken-carbonara' OR (SourceUrl IS NULL AND Title=N'Low Carb Chicken Carbonara Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Low Carb Chicken Carbonara Recipe', N'Lunch', N'An Italian favorite with a healthy twist! Herbed baked chicken is dressed with carbonara sauce and served on a bed of spaghetti squash for low carb comfort food!', 320, 47, 17, 4, NULL, 1, 10093, N'https://www.muscleandstrength.com/recipes/low-carb-chicken-carbonara', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/chicken-carbonara-recipe.jpg', N'Serves 1.', N'Preheat oven to 300F Add oil to saute pan and set on medium-high heat Season chicken with salt, pepper and desired seasonings. Italian seasoning is my personal choice! Once oil is close to reaching its smoke-point (or when you see ripples in oil), add chicken and sear each side until golden brown. Remove from pan and put on baking sheet and into the oven Place saute pan back onto heat and start deglazing pan with tomatoes. After a few seconds, add garlic, mushrooms, and snow peas. Saute until fragrant and mushrooms are golden brown. Deglaze again with white wine and let cook until all wine has dissipated Add milk and reduce by half, then add Arrowroot (mixed into a slurry with some water) and thicken until desired consistency is reached Remove chicken from oven when internal temperature of 160F is reached. Let rest until it reaches 165F While chicken rests, toss spaghetti squash into sauce Serve baked chicken on top of sauced spaghetti squash and enjoy!', N'["High Protein Recipes","Low Carb Recipes","Lunch Recipes","Dinner Recipes"]', N'{"calories_kcal":"320","protein_g":"47","carbs_g":"17","fat_g":"4"}', 25800);
END
