DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/rj-perkins-pumpkin-spice-pancakes.html' OR (SourceUrl IS NULL AND Title=N'RJ Perkins'' Pumpkin Spice Pancakes Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'RJ Perkins'' Pumpkin Spice Pancakes Recipe', N'Breakfast', N'This is a moderate protein and high carb breakfast meal perfect for fall by natural bodybuilder and Scivation sponsored athlete RJ Perkins.', 460, 25, 75, 7, NULL, 1, 10095, N'https://www.muscleandstrength.com/recipes/rj-perkins-pumpkin-spice-pancakes.html', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/rj-perkins-4501.jpg', N'Without adding any water or milk to the batter using a 1/4 measuring cup to pour on batter you can get 6 - 8 pancakes. If you add a 1/4 cup of water or milk to the mix using a 1/4 measuring cup to pour on batter you can get 8 - 10 pancakes.', N'Fall is here and "pumpkin" seems to be in everything, pumpkin pie, pumpkin muffins, even pumpkin coffee. I love fall and the tastes of fall especially pumpkin, so I decided to take one of my favorite tastes and make a recipe for my favorite meal of the day ''BREAKFAST"! This is a high carb, moderate protein, and very low fat recipe that I use mainly for my breakfast/pre-wo meal being I train first thing in the am. Pre-heat your skillet or griddle on a medium temperature depending on your stove. Grind the oats into a powder/flower using either a coffee grinder or blender. Add and mix (dry ingredients) oat powder/flour, cinnamon, no-calorie sweetener, & baking powder into a large mixing bowl. In a separate mixing bowl mix the egg whites and Libby''s pumpkin together. The Libby''s pumpkin is like an apple sauce consistency so it will mix with the egg white easily. Pour the egg white and pumpkin mix into the dry ingredients bowl and blend together. Now the consistency of the mix may be to your liking already in which you may want to start making the pancakes. I prefer to add a 1/4 cup of water which I realized allows me to make an extra pancake or two. Once your batter is to your liking spray your skillet/griddle with non-stick spray or whatever product you use for non-stick purposes. Scoop the batter using a 1/4 cup measuring cup and pour batter onto the skillet/griddle. When you see light bubbles start to form and the edges of the pancakes get firm they are ready to flip. Serve and enjoy, you can top with what you like. I do not use anything as the pancakes are sweet and taste perfect by themselves. Note: If you need or want added carbs you can add milk to the mix as well as if you need more protein you can add vanilla protein powder.', N'["Breakfast Recipes"]', N'{"calories_kcal":"460","protein_g":"25","carbs_g":"75","fat_g":"7"}', 25500);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'RJ Perkins'' Pumpkin Spice Pancakes Recipe', MealType=N'Breakfast', Description=N'This is a moderate protein and high carb breakfast meal perfect for fall by natural bodybuilder and Scivation sponsored athlete RJ Perkins.', CaloriesKcal=460, ProteinG=25, CarbsG=75, FatsG=7,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10095, SourceUrl=N'https://www.muscleandstrength.com/recipes/rj-perkins-pumpkin-spice-pancakes.html', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/rj-perkins-4501.jpg', ServingSuggestion=N'Without adding any water or milk to the batter using a 1/4 measuring cup to pour on batter you can get 6 - 8 pancakes. If you add a 1/4 cup of water or milk to the mix using a 1/4 measuring cup to pour on batter you can get 8 - 10 pancakes.', ContentText=N'Fall is here and "pumpkin" seems to be in everything, pumpkin pie, pumpkin muffins, even pumpkin coffee. I love fall and the tastes of fall especially pumpkin, so I decided to take one of my favorite tastes and make a recipe for my favorite meal of the day ''BREAKFAST"! This is a high carb, moderate protein, and very low fat recipe that I use mainly for my breakfast/pre-wo meal being I train first thing in the am. Pre-heat your skillet or griddle on a medium temperature depending on your stove. Grind the oats into a powder/flower using either a coffee grinder or blender. Add and mix (dry ingredients) oat powder/flour, cinnamon, no-calorie sweetener, & baking powder into a large mixing bowl. In a separate mixing bowl mix the egg whites and Libby''s pumpkin together. The Libby''s pumpkin is like an apple sauce consistency so it will mix with the egg white easily. Pour the egg white and pumpkin mix into the dry ingredients bowl and blend together. Now the consistency of the mix may be to your liking already in which you may want to start making the pancakes. I prefer to add a 1/4 cup of water which I realized allows me to make an extra pancake or two. Once your batter is to your liking spray your skillet/griddle with non-stick spray or whatever product you use for non-stick purposes. Scoop the batter using a 1/4 cup measuring cup and pour batter onto the skillet/griddle. When you see light bubbles start to form and the edges of the pancakes get firm they are ready to flip. Serve and enjoy, you can top with what you like. I do not use anything as the pancakes are sweet and taste perfect by themselves. Note: If you need or want added carbs you can add milk to the mix as well as if you need more protein you can add vanilla protein powder.', CategoriesJson=N'["Breakfast Recipes"]', SourceMacrosJson=N'{"calories_kcal":"460","protein_g":"25","carbs_g":"75","fat_g":"7"}', ReadCount=25500
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'80 grams old fashioned oats');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'4 egg whites');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'150 grams Libby''s Solid Packed Pumpkin canned');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'1 tbsp cinnamon');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 5, N'1/4 cup Splenda/Stevia/no-calorie sweetener');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 6, N'1 tsp baking powder');
