INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 2, N'Grind the oats into a powder/flower using either a coffee grinder or blender.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'Add and mix (dry ingredients) oat powder/flour, cinnamon, no-calorie sweetener, & baking powder into a large mixing bowl.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'In a separate mixing bowl mix the egg whites and Libby''s pumpkin together. The Libby''s pumpkin is like an apple sauce consistency so it will mix with the egg white easily.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 5, N'Pour the egg white and pumpkin mix into the dry ingredients bowl and blend together. Now the consistency of the mix may be to your liking already in which you may want to start making the pancakes. I prefer to add a 1/4 cup of water which I realized allows me to make an extra pancake or two.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'Once your batter is to your liking spray your skillet/griddle with non-stick spray or whatever product you use for non-stick purposes. Scoop the batter using a 1/4 cup measuring cup and pour batter onto the skillet/griddle.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 7, N'When you see light bubbles start to form and the edges of the pancakes get firm they are ready to flip.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 8, N'Serve and enjoy, you can top with what you like. I do not use anything as the pancakes are sweet and taste perfect by themselves.');
GO

