IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Chocolate Peanut Butter Protein Granola Recipe', N'Snack', N'Who doesn''t love some sweet granola? Give this recipe for chocolate peanut butter protein granola a try. Eat it plain or use it to top your yogurt!', 116, 5, 14, 5, NULL, 1, 10149, N'https://www.muscleandstrength.com/recipes/chocolate-peanut-butter-granola', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/choc-pb-granola-feature.jpg', N'makes 10 servings', N'Preheat oven to 350 degrees F Line a baking sheet with foil and coat with non stick spray Mix together your dry ingredients: oats, protein powder, peanut powder, cocoa powder and baking powder Add your wet ingredients to the bowl: egg whites, honey and peanut butter. Mix until small clusters form (this will take a minute or so) Evenly spread onto your baking sheet Bake for about 12 minutes Remove from the oven and give the granola a stir Return to the oven and bake for an additional 10 minutes Allow to cool Add in (or drizzle on top) peanut butter and/or chocolate chips Store in a sealed container Notes: *You can substitute the chocolate egg whites for plain eggwhites, however the chocolate flavor will be a bit more mild', N'["Snack Recipes","Vegetarian Recipes"]', N'{"calories_kcal":"116","protein_g":"5","carbs_g":"14","fat_g":"5"}', 15100);
END
