    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Cinnamon French Toast With Strawberries Recipe', N'Breakfast', N'This high protein and healthy cinnamon French toast option is extremely easy to make and contains fewer than 300 calories and 16 grams of protein per serving.', 292, 16, 39, 8, NULL, 1, 10158, N'https://www.muscleandstrength.com/recipe/cinnamon-french-toast-strawberries', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/cinnamon-french-toast-450.jpg', N'1 serving.', N'What you need: Cooking Spray/Olive Oil Skillet/Pan Spatula Whisk Medium/Large Bowl Measuring Spoons Scale Instructions. Combine eggs, milk, cinnamon, vanilla and whisk in bowl until well blended. Prepare skillet with oil and place on medium high heat. Dip slices of bread into egg mixture, on both sides (do not allow bread to soak in mixture, this will result in soggy french toast). Place bread slices in skillet and brown each side flipping once, cook 3-5 minutes on each side. Remove french toast from skillet. Plate as desire, top with Strawberries or fruit of choice and drizzle with 100% Pure Maple Syrup (optional). Enjoy! Toppings (Optional) 100% Pure Maple Syrup StrawberriesToppings (Optional)', N'["Breakfast Recipes"]', N'{"calories_kcal":"292","protein_g":"16","carbs_g":"39","fat_g":"8"}', 13800);
END
