IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Low Calorie Chocolate Protein Cupcakes Recipe', N'Snack', N'Anytime is a good time to celebrate with these low calorie cupcakes that not only taste incredible but deliver a solid dose of protein as well!', 121, 14, 5, 5, NULL, 1, 10166, N'https://www.muscleandstrength.com/recipes/low-calorie-chocolate-protein-cupcakes', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/chocolate_protein_cupcakes.jpg', N'Makes 12 cupcakes.', N'Preheat oven to 325 degrees F Line 12 cupcake tins with paper liners (or spray pan) Mix together chocolate protein powder and baking powder Add in egg whites, melted coconut oil, milk, applesauce Mix until just combined (do not over mix) Evenly divide batter between 12 cupcake liners Bake for ~7 minutes (or until tops are just set)** Remove from oven and allow to set While cupcakes cool, mix together greek yogurt and vanilla protein powder Frost as desired Finish off with sprinkles, if using. Notes: *Use your favorite protein powder **Do not over bake. When working with whey protein powder, they will continue to set after they are removed from the oven.', N'["Snack Recipes"]', N'{"calories_kcal":"121","protein_g":"14","carbs_g":"5","fat_g":"5"}', 13000);
END
