INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 2, N'Add your Greens supplement of choice into the blender. 2 cups of spinach can also be substituted here if you''d like.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'Mix in the tablespoon of chia seeds into the blender. If you''re not a fan of chia seeds you can substitute almond or peanut butter instead.');
