DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipe/peanut-butter-maple-banana-bread' OR (SourceUrl IS NULL AND Title=N'Peanut Butter Maple Glaze Banana Bread Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Peanut Butter Maple Glaze Banana Bread Recipe', N'Snack', N'Satisfy your urge for peanut butter with this flavor-packed, maple-glazed banana bread recipe from Nikia Dyson. Each swerving contains only 122 calories.', 122, 4, 21, 4, NULL, 1, 10187, N'https://www.muscleandstrength.com/recipe/peanut-butter-maple-banana-bread', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/peanut-butter-450_0.jpg', N'1 slice.', N'What you need: Two Large Bowls or Mixer and Larger Bowl One Small Bowl Spoon Measuring Spoons Whisk or Fork Loaf Pan Cooking Spray/Oil Scale Seran Wrap Knife Tips/Suggestions: KFF baking flour blend (Makes 3 Cups): 128g brown rice flour, 128g oat flour, 43g tapioca flour, 85g potato starch. Allow bread to cool for 10-15 minutes before cutting. Cut in to 12-16 thick slices, based on your preference. Bread can be cut as stated above, but ABSOLUTE best results are after allowing to cool in refrigerator overnight, slicing in the morning, and toasting or heating in microwave (Just a suggestion, but not necessary - I usually don’t wait :-). Bread crust may be slightly harder to the touch, this is normal. After cooling and refrigerating, the crust will moisten yielding a perfect loaf. It is always better the next day! I use loaf pans smaller than 9x5, this yields a loaf with a higher rise. Directions: Preheat oven to 350 degrees. Lightly spray loaf pan and set aside. Combine all dry Ingredients in large bowl, set aside. Combine all wet Ingredient in bowl, add wet ingredients to dry and gently combine. Do not over beat. Pour batter in loaf pan and smooth out. Place in oven and bake for 55-60 minutes. At the 40-45 min mark, check bread for doneness and place small piece of tented foil over the top (This will keep it from browning too much). **All ovens are not created equal, be sure to watch your bread once it reaches the 40-45 minute mark. Remove loaf from oven; allow to cool in loaf pan for 5mins. Remove from loaf pan and place on wire rack (or plate) to cool. (For Glaze) Soften peanut butter in small bowl with a spoon or fork (or microwave for 5-10 seconds to soften). Add milk, maple and combine. Drizzle peanut butter maple glaze over bread loaf. Allow to cool for 10-15 minutes before cutting. Cut in to 12 -16 slices, based on your preference. To store, tightly wrap in Seran wrap. Keep in refrigerator until ready to use or place in a container with a lid. Enjoy! This recipe yields 14 slices.', N'["Snack Recipes"]', N'{"calories_kcal":"122","protein_g":"4","carbs_g":"21","fat_g":"4"}', 10400);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Peanut Butter Maple Glaze Banana Bread Recipe', MealType=N'Snack', Description=N'Satisfy your urge for peanut butter with this flavor-packed, maple-glazed banana bread recipe from Nikia Dyson. Each swerving contains only 122 calories.', CaloriesKcal=122, ProteinG=4, CarbsG=21, FatsG=4,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10187, SourceUrl=N'https://www.muscleandstrength.com/recipe/peanut-butter-maple-banana-bread', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/peanut-butter-450_0.jpg', ServingSuggestion=N'1 slice.', ContentText=N'What you need: Two Large Bowls or Mixer and Larger Bowl One Small Bowl Spoon Measuring Spoons Whisk or Fork Loaf Pan Cooking Spray/Oil Scale Seran Wrap Knife Tips/Suggestions: KFF baking flour blend (Makes 3 Cups): 128g brown rice flour, 128g oat flour, 43g tapioca flour, 85g potato starch. Allow bread to cool for 10-15 minutes before cutting. Cut in to 12-16 thick slices, based on your preference. Bread can be cut as stated above, but ABSOLUTE best results are after allowing to cool in refrigerator overnight, slicing in the morning, and toasting or heating in microwave (Just a suggestion, but not necessary - I usually don’t wait :-). Bread crust may be slightly harder to the touch, this is normal. After cooling and refrigerating, the crust will moisten yielding a perfect loaf. It is always better the next day! I use loaf pans smaller than 9x5, this yields a loaf with a higher rise. Directions: Preheat oven to 350 degrees. Lightly spray loaf pan and set aside. Combine all dry Ingredients in large bowl, set aside. Combine all wet Ingredient in bowl, add wet ingredients to dry and gently combine. Do not over beat. Pour batter in loaf pan and smooth out. Place in oven and bake for 55-60 minutes. At the 40-45 min mark, check bread for doneness and place small piece of tented foil over the top (This will keep it from browning too much). **All ovens are not created equal, be sure to watch your bread once it reaches the 40-45 minute mark. Remove loaf from oven; allow to cool in loaf pan for 5mins. Remove from loaf pan and place on wire rack (or plate) to cool. (For Glaze) Soften peanut butter in small bowl with a spoon or fork (or microwave for 5-10 seconds to soften). Add milk, maple and combine. Drizzle peanut butter maple glaze over bread loaf. Allow to cool for 10-15 minutes before cutting. Cut in to 12 -16 slices, based on your preference. To store, tightly wrap in Seran wrap. Keep in refrigerator until ready to use or place in a container with a lid. Enjoy! This recipe yields 14 slices.', CategoriesJson=N'["Snack Recipes"]', SourceMacrosJson=N'{"calories_kcal":"122","protein_g":"4","carbs_g":"21","fat_g":"4"}', ReadCount=10400
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'256g (2 cups) KFF Flour Blend (Or use flour of choice such as Oat, Barley, Brown Rice, etc. You can find my flour blend recipe below in notes)');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'2 ¼ tsp Baking Powder (Preferably Gluten & Aluminum Free/Low Sodium)');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'½ tsp Baking Soda');
