INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'Pour batter in loaf pan and smooth out. Place in oven and bake for 55-60 minutes. At the 40-45 min mark, check bread for doneness and place small piece of tented foil over the top (This will keep it from browning too much). **All ovens are not created equal, be sure to watch your bread once it reaches the 40-45 minute mark.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'Remove loaf from oven; allow to cool in loaf pan for 5mins.');
