INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 9, N'To store, tightly wrap in Seran wrap. Keep in refrigerator until ready to use or place in a container with a lid.');
