DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/chocolate-peanut-butter-caramel-apples' OR (SourceUrl IS NULL AND Title=N'Healthy Chocolate Peanut Butter Caramel Apples Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Healthy Chocolate Peanut Butter Caramel Apples Recipe', N'Snack', N'Sweeten up your Halloween with these crispy apples dripping in protein packed chocolate and plain peanut butter!', 271, 13, 47, 8, NULL, 1, 10198, N'https://www.muscleandstrength.com/recipes/chocolate-peanut-butter-caramel-apples', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/halloween_apples_macros.jpg', N'Makes 3 servings.', N'Using a knife, cut “X” into top of apple Stick the straw into the top of the apple where you made the “X” Place apples on parchment paper Melt caramels with 1 tsp water Drizzle caramel over the top of each apple Place in fridge to set Add chocolate peanut butter and 1 tsp coconut oil to a ziplock bag and mix Cut a small whole in the corner of the ziplock bag Remove apples from refrigerator and drizzle with chocolate peanut butter Place back in refrigerator Add plain peanut butter and 1 tsp coconut oil to a second ziplock bag and mix Cut a small whole in the corner of the ziplock bag Drizzle peanut butter over chocolate layer Add sprinkles, if desired Place back in refrigerator to set Enjoy! Notes: *You can significantly decrease the fat content in this recipe by swapping out the peanut butter for peanut butter powder. Mix peanut powder with water until peanut butter like consistency is reached and then follow directions as listed above. **Macros based on Apples made with peanut butter powder. Macros for regular peanut butter as follows: 1 Apple With Regular Peanut Butter Calories: 545 Protein: 25g Carbs: 57g Fat: 23g', N'["Snack Recipes"]', N'{"calories_kcal":"271","protein_g":"13","carbs_g":"47","fat_g":"8"}', 6000);
END
